"""Render the assembled book and build a keyboard-accessible facing-page viewer."""
from pathlib import Path
import json,subprocess,html
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs/publication/whole-book-order-preview'
checks=json.loads((DOC/'CHECKS.json').read_text());pages=json.loads((DOC/'PAGE-MAP.json').read_text())
images=DOC/'pages';images.mkdir(exist_ok=True)
subprocess.run(['pdftoppm','-r','110','-jpeg','-jpegopt','quality=85','-cropbox',str(ROOT/checks['pdf']),str(images/'page')],check=True)
assert len(list(images.glob('page-*.jpg')))==checks['pdfPages']
for p in pages:p['image']=f"pages/page-{p['pdfPage']:03}.jpg"
pdf='../../../'+checks['pdf']
template=r'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Vegetable Guru · Whole-book order preview</title><style>
@font-face{font-family:Nunito;src:url('/fonts/richer-a-6.woff2');font-weight:100 1000}*{box-sizing:border-box}body{margin:0;background:#d9dfcf;color:#173e2c;font:17px/1.5 Nunito,sans-serif}header,main,footer{max-width:1640px;margin:auto;padding:24px 30px}header{max-width:1120px}h1{font-size:42px;line-height:1.1;margin:8px 0 18px}h2{font-size:25px;margin:0 0 12px}.eyebrow{font-size:13px;font-weight:900;letter-spacing:1px}.intro{max-width:930px}.note{background:#fff8e9;padding:18px 22px;border-left:4px solid #a44007}.note ul{padding-left:22px;margin:8px 0}.note li{margin:6px 0}.small,footer{font-size:14px}a{color:#064d32}.button,button{font:800 16px Nunito;background:#173e2c;color:#fff8e9;border:0;border-radius:5px;padding:10px 15px;text-decoration:none;cursor:pointer}button:disabled{opacity:.4;cursor:default}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:16px;background:#fff8e9;border-radius:8px}.toolbar label{font-size:14px;font-weight:800}select,input{font:inherit;color:inherit;padding:8px;border:1px solid #9daa92;background:#fffdf6;border-radius:4px;max-width:100%}select{max-width:430px}input{width:80px}.position{font-size:14px;font-weight:800}.spread{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:20px;align-items:start}.spread figure{margin:0;min-width:0}.spread img{display:block;width:100%;box-shadow:0 2px 14px #173e2c22;background:white}.spread figcaption{font-size:14px;margin:9px 2px 18px}.placeholder{aspect-ratio:185/240}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:15px;margin:20px 0}.thumb{background:none;border:0;color:#173e2c;padding:0;min-width:0;font:13px Nunito}.thumb img{width:100%;display:block;margin-bottom:5px}details{margin-top:30px}summary{cursor:pointer;font-weight:900}.links{display:flex;gap:18px;flex-wrap:wrap;margin:15px 0}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:750px){header,main,footer{padding:18px 12px}h1{font-size:33px}.spread{gap:4px}.spread figcaption{font-size:11px}.toolbar{padding:12px;gap:8px}select{width:100%}.toolbar .jump{width:100%}.placeholder{display:block}}
</style></head><body><header><div class="eyebrow">THE VEGETABLE GURU · WHOLE-BOOK ORDER REVIEW · 12 OCTOBER 2026</div><h1>See how the book flows</h1><p class="intro">The complete imperial preview: latest opening copy, the current contents draft, 44 vegetable guides, 14 Troubles guides, all approved additional pages and the approved index with updated references. Selected G2 and preferred B5 covers are included.</p><p><a class="button" href="__PDF__" target="_blank">Open the whole-book PDF · __SIZE__ MB</a></p><p class="small">170 interior pages plus four cover leaves: 174 PDF pages. Printed page numbers are shown below each preview. The PDF has bookmarks and clickable index references.</p><section class="note"><h2>Page ordering to settle</h2><ul><li><strong>Why Grow Your Own is currently page 9.</strong> Moving it to page 7 would let the two How to use pages face each other at 8–9.</li><li><strong>Several technique pairs cross a page turn:</strong> Beds and paths at 153–154, Digging at 157–158, and Compost at 163–164. One page before Growing Techniques would shift all three into facing spreads. We can consider a section opener when agreeing the order.</li><li><strong>Four blanks remain at 17, 71, 89 and 93</strong> to preserve facing crop openings. Inside covers are also blank.</li></ul><p class="small">This preview keeps the current 170-page proposal so those choices are visible. The contents still need refinement. Opening placeholders and trial stock-image placements remain; the page order has not been approved.</p></section></header><main id="reader"><div class="toolbar"><button id="previous" type="button">← Previous</button><button id="next" type="button">Next →</button><span class="position" id="position" aria-live="polite"></span><div class="jump"><label for="jump">Jump to</label> <select id="jump"></select></div><form id="go"><label for="folio">Book page</label> <input id="folio" type="number" min="1" max="170" value="1"><button type="submit">Go</button></form></div><p class="small">Use the left and right arrow keys to turn spreads. Select a page image to open that page in the PDF.</p><div class="spread" id="spread" aria-live="polite"></div><details id="overview"><summary>See every page in order</summary><div class="gallery" id="gallery"></div></details><div class="links"><a href="../contents-update/REVIEW.html">Contents on their own</a><a href="../book-index/REVIEW.html">Approved index reference</a><a href="README.md">Preview notes</a></div></main><footer>A screen review assembled from saved sources; artwork is reduced for browsing and native text remains sharp in the PDF. All original proofs are preserved. This is not a Bookvault upload file.</footer><script>
const pages=__PAGES__,pdf=__PDFJSON__;let spreadIndex=0;const last=Math.floor(pages.length/2),spread=document.getElementById('spread'),jump=document.getElementById('jump');
const label=p=>p.folio===null?p.label:'Page '+p.folio+' · '+p.label;
const imagePath=p=>p.image;
function show(n,updateHash=true){spreadIndex=Math.max(0,Math.min(last,n));const indices=spreadIndex===0?[-1,0]:[spreadIndex*2-1,spreadIndex*2];spread.replaceChildren();for(const i of indices){const p=pages[i],f=document.createElement('figure');if(!p){f.className='placeholder';f.setAttribute('aria-hidden','true');spread.append(f);continue;}const a=document.createElement('a');a.href=pdf+'#page='+p.pdfPage;a.target='_blank';const img=document.createElement('img');img.src=imagePath(p);img.alt=label(p);img.decoding='async';a.append(img);const caption=document.createElement('figcaption');caption.textContent=label(p);f.append(a,caption);spread.append(f);}document.getElementById('previous').disabled=spreadIndex===0;document.getElementById('next').disabled=spreadIndex===last;document.getElementById('position').textContent='Spread '+(spreadIndex+1)+' of '+(last+1);if(updateHash)history.replaceState(null,'','#spread='+spreadIndex);}
function goPdf(i){show(Math.floor((i+1)/2));}
let prevKind='';pages.forEach((p,i)=>{const first=p.folio===null?p.kind==='cover':p.kind==='contents'?p.folio===4:p.kind==='index'?p.folio===167:p.label.endsWith(' — continued')?false:true;if(first&&p.kind!=='blank'){const o=document.createElement('option');o.value=i;o.textContent=label(p);jump.append(o);}});
jump.addEventListener('change',()=>goPdf(Number(jump.value)));document.getElementById('previous').onclick=()=>show(spreadIndex-1);document.getElementById('next').onclick=()=>show(spreadIndex+1);document.getElementById('go').onsubmit=e=>{e.preventDefault();const f=Number(document.getElementById('folio').value);if(f>=1&&f<=170)goPdf(f+1);};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(spreadIndex+1);}if(e.key==='ArrowLeft'){e.preventDefault();show(spreadIndex-1);}});
document.getElementById('overview').addEventListener('toggle',e=>{const g=document.getElementById('gallery');if(!e.target.open||g.children.length)return;pages.forEach((p,i)=>{const b=document.createElement('button');b.className='thumb';const img=document.createElement('img');img.src=imagePath(p);img.alt=label(p);img.loading='lazy';b.append(img,document.createTextNode(p.folio===null?p.label:String(p.folio)));b.onclick=()=>{goPdf(i);document.getElementById('reader').scrollIntoView({behavior:'smooth'});};g.append(b);});});
const match=location.hash.match(/spread=(\d+)/);show(match?Number(match[1]):0,false);
</script></body></html>'''
template=template.replace('__PDF__',html.escape(pdf)).replace('__SIZE__',f"{checks['bytes']/1024**2:.1f}").replace('__PAGES__',json.dumps(pages,ensure_ascii=False).replace('</','<\\/')).replace('__PDFJSON__',json.dumps(pdf))
(DOC/'REVIEW.html').write_text(template)
(DOC/'PAGE-MAP.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'renderedPages':len(pages),'facingViews':len(pages)//2+1,'review':str((DOC/'REVIEW.html').relative_to(ROOT))}))
